CREATE TABLE IF NOT EXISTS commission_schemes (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, company_id INT UNSIGNED NULL, category_id INT UNSIGNED NULL, product_id INT UNSIGNED NULL,
 name VARCHAR(150) NOT NULL, scheme_type VARCHAR(50) NOT NULL, basis ENUM('quantity','sales_amount','purchase_amount','gross_profit','target_achievement','collection_amount','collection_percentage','growth_percentage','invoice_count') NOT NULL,
 calculation_method ENUM('fixed_rate','percentage','target_achievement','volume_slab','amount_slab','growth','collection','payment_timing') NOT NULL,
 slab_mode ENUM('whole','progressive') NOT NULL DEFAULT 'whole', stacking_mode ENUM('stack','highest_only','exclusive','conditional_stack') NOT NULL DEFAULT 'stack', priority INT NOT NULL DEFAULT 100,
 effective_from DATE NOT NULL, effective_to DATE NULL, status ENUM('draft','active','inactive','locked','cancelled') NOT NULL DEFAULT 'draft', notes TEXT NULL, created_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 KEY idx_scheme_tenant_active (tenant_id,status,effective_from,effective_to), KEY idx_scheme_scope (tenant_id,company_id,category_id,product_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS commission_slabs (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, scheme_id BIGINT UNSIGNED NOT NULL, from_value DECIMAL(18,4) NOT NULL, to_value DECIMAL(18,4) NULL, rate DECIMAL(18,4) NOT NULL DEFAULT 0, rate_type ENUM('fixed','percentage') NOT NULL DEFAULT 'fixed', bonus_amount DECIMAL(18,2) NOT NULL DEFAULT 0, KEY idx_slabs_scheme (scheme_id,from_value), CONSTRAINT fk_slabs_scheme FOREIGN KEY (scheme_id) REFERENCES commission_schemes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS commission_conditions (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, scheme_id BIGINT UNSIGNED NOT NULL, group_no INT NOT NULL DEFAULT 1, boolean_operator ENUM('AND','OR') NOT NULL DEFAULT 'AND', field_name VARCHAR(50) NOT NULL, comparison_operator ENUM('=','!=','>','>=','<','<=','BETWEEN') NOT NULL, value_from VARCHAR(100) NOT NULL, value_to VARCHAR(100) NULL, KEY idx_conditions_scheme (scheme_id,group_no), CONSTRAINT fk_conditions_scheme FOREIGN KEY (scheme_id) REFERENCES commission_schemes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS commission_targets (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, scheme_id BIGINT UNSIGNED NULL, company_id INT UNSIGNED NULL, category_id INT UNSIGNED NULL, product_id INT UNSIGNED NULL, period_type ENUM('daily','weekly','monthly','quarterly','half_yearly','yearly','custom') NOT NULL, period_start DATE NOT NULL, period_end DATE NOT NULL, target_basis ENUM('quantity','sales_amount') NOT NULL, target_method ENUM('fixed','previous_month_percent','previous_year_percent','average_percent','custom') NOT NULL DEFAULT 'fixed', target_value DECIMAL(18,4) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, KEY idx_targets_lookup (tenant_id,period_start,period_end,company_id,product_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS commission_calculations (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, scheme_id BIGINT UNSIGNED NOT NULL, company_id INT UNSIGNED NULL, category_id INT UNSIGNED NULL, product_id INT UNSIGNED NULL, sale_id INT UNSIGNED NULL, period_start DATE NOT NULL, period_end DATE NOT NULL, basis_value DECIMAL(18,4) NOT NULL DEFAULT 0, target_value DECIMAL(18,4) NULL, achievement_percentage DECIMAL(10,4) NULL, slab_id BIGINT UNSIGNED NULL, calculation_method VARCHAR(50) NOT NULL, breakdown_json JSON NOT NULL, gross_commission DECIMAL(18,2) NOT NULL DEFAULT 0, adjustment DECIMAL(18,2) NOT NULL DEFAULT 0, deduction DECIMAL(18,2) NOT NULL DEFAULT 0, net_commission DECIMAL(18,2) NOT NULL DEFAULT 0, status ENUM('calculated','pending','approved','received','adjusted','cancelled','reversed') NOT NULL DEFAULT 'calculated', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, KEY idx_calculation_tenant_period (tenant_id,period_start,period_end,status), KEY idx_calculation_scheme (scheme_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS commission_adjustments (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, company_id INT UNSIGNED NOT NULL, scheme_id BIGINT UNSIGNED NULL, calculation_id BIGINT UNSIGNED NULL, period_start DATE NOT NULL, period_end DATE NOT NULL, amount DECIMAL(18,2) NOT NULL, reference_no VARCHAR(100) NULL, description TEXT NOT NULL, attachment_path VARCHAR(255) NULL, status ENUM('pending','approved','cancelled') NOT NULL DEFAULT 'pending', created_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, KEY idx_adjustment_tenant_company_period (tenant_id,company_id,period_start,period_end)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS commission_settlements (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, company_id INT UNSIGNED NOT NULL, period_start DATE NOT NULL, period_end DATE NOT NULL, calculated_amount DECIMAL(18,2) NOT NULL DEFAULT 0, statement_amount DECIMAL(18,2) NULL, adjustment_amount DECIMAL(18,2) NOT NULL DEFAULT 0, final_amount DECIMAL(18,2) NOT NULL DEFAULT 0, received_amount DECIMAL(18,2) NOT NULL DEFAULT 0, payment_method VARCHAR(50) NULL, reference_no VARCHAR(100) NULL, settlement_date DATE NULL, status ENUM('calculated','pending','approved','received','adjusted','cancelled') NOT NULL DEFAULT 'calculated', notes TEXT NULL, created_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, KEY idx_settlement_tenant_company_period (tenant_id,company_id,period_start,period_end)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS commission_ledger (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, tenant_id INT UNSIGNED NOT NULL, company_id INT UNSIGNED NOT NULL, calculation_id BIGINT UNSIGNED NULL, adjustment_id BIGINT UNSIGNED NULL, settlement_id BIGINT UNSIGNED NULL, entry_date DATE NOT NULL, entry_type ENUM('calculated','adjustment','approval','receipt','reversal') NOT NULL, debit DECIMAL(18,2) NOT NULL DEFAULT 0, credit DECIMAL(18,2) NOT NULL DEFAULT 0, running_balance DECIMAL(18,2) NOT NULL DEFAULT 0, reference_no VARCHAR(100) NULL, description VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, KEY idx_comm_ledger_tenant_company_date (tenant_id,company_id,entry_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
